SELECT model, method, catalog_size, COUNT(*) AS queries, AVG(mrr5) AS mrr5, AVG(recall1) AS recall1, AVG(recall5) AS recall5, AVG(hit1) AS hit1, AVG(hit5) AS hit5, AVG(ndcg5) AS ndcg5, AVG(complete5) AS complete5, AVG(candidate_recall) AS candidate_recall, AVG(candidate_hit) AS candidate_hit, AVG(shortlist_mrr5) AS shortlist_mrr5 FROM benchmark_per_query GROUP BY model, method, catalog_size ORDER BY model, method, catalog_size;
